#!/usr/bin/env node
'use strict';

const path = require('node:path');
const {
  TodoError,
  loadTodos,
  saveTodos,
  addTodo,
  findTodo,
  deleteTodo,
  parseId,
  formatTodos,
} = require('./lib/todos');

const USAGE = `Usage: node index.js <command> [arguments]

Commands:
  add <text>       Add a new todo
  list             List all todos
  complete <id>    Mark a todo as done
  delete <id>      Delete a todo
  help             Show this help message`;

// Returns the single ID argument for `complete` / `delete`.
function idArg(command, rest) {
  if (rest.length === 0) {
    throw new TodoError(`Missing todo ID. Usage: node index.js ${command} <id>`);
  }
  if (rest.length > 1) {
    throw new TodoError(`Too many arguments. Usage: node index.js ${command} <id>`);
  }
  return parseId(rest[0]);
}

// Runs one command and returns the process exit code.
function run(args, file) {
  const [command, ...rest] = args;

  switch (command) {
    case 'add': {
      if (rest.length === 0) {
        throw new TodoError('Missing todo text. Usage: node index.js add "<text>"');
      }
      const todos = loadTodos(file);
      // Accept unquoted text too: `add Buy groceries` adds "Buy groceries".
      const todo = addTodo(todos, rest.join(' '));
      saveTodos(file, todos);
      console.log(`Added todo #${todo.id}: ${todo.text}`);
      return 0;
    }

    case 'list': {
      if (rest.length > 0) {
        throw new TodoError('Too many arguments. Usage: node index.js list');
      }
      const todos = loadTodos(file);
      if (todos.length === 0) {
        console.log('No todos yet. Add one with: node index.js add "<text>"');
      } else {
        console.log(formatTodos(todos));
      }
      return 0;
    }

    case 'complete': {
      const id = idArg(command, rest);
      const todos = loadTodos(file);
      const todo = findTodo(todos, id);
      if (todo.completed) {
        console.log(`Todo #${id} is already completed: ${todo.text}`);
        return 0;
      }
      todo.completed = true;
      saveTodos(file, todos);
      console.log(`Completed todo #${id}: ${todo.text}`);
      return 0;
    }

    case 'delete': {
      const id = idArg(command, rest);
      const todos = loadTodos(file);
      const todo = deleteTodo(todos, id);
      saveTodos(file, todos);
      console.log(`Deleted todo #${id}: ${todo.text}`);
      return 0;
    }

    case 'help':
    case '--help':
    case '-h':
      console.log(USAGE);
      return 0;

    case undefined:
      console.error(USAGE);
      return 1;

    default:
      console.error(`Error: Unknown command "${command}".\n\n${USAGE}`);
      return 1;
  }
}

try {
  process.exitCode = run(process.argv.slice(2), path.join(process.cwd(), 'todos.json'));
} catch (err) {
  console.error(`Error: ${err.message}`);
  process.exitCode = 1;
}
