    assert.equal(result.code, 0);
    assert.equal(result.stdout, '1. [ ] Buy groceries\\n3. [ ] Write report\\n');
    assert.equal(result.stderr, '');
  });

  it('leaves plain list showing every todo', () => {
    run('add', 'a');
    run('add', 'b');
    run('complete', '1');
