  it('replaces the text and keeps id, completed status and createdAt', () => {
    const [first, second] = readTodos();
    const result = run('edit', '2', 'Walk the cat');
    assert.equal(result.code, 0);
    assert.equal(result.stdout, 'Edited todo #2: Walk the cat\\n');
    assert.equal(result.stderr, '');
    assert.deepEqual(readTodos(), [first, { ...second, text: 'Walk the cat' }]);
  });

  it('joins unquoted words and trims whitespace', () => {
